package com.jnapanam.sportszone.content.dto;import com.jnapanam.sportszone.content.model.*;import java.time.Instant;import java.util.UUID;public record AnnouncementResponse(UUID id,String title,String titleKn,String body,String bodyKn,int priority,Instant publishFrom,Instant publishUntil,ContentStatus status){public static AnnouncementResponse from(Announcement a){return new AnnouncementResponse(a.getId(),a.getTitle(),a.getTitleKn(),a.getBody(),a.getBodyKn(),a.getPriority(),a.getPublishFrom(),a.getPublishUntil(),a.getStatus());}}